def rot_n(text, n):
    result = []
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            rotated = chr((ord(char) - base + n) % 26 + base)
            result.append(rotated)
        else:
            result.append(char)
    return ''.join(result)

